// Bundles render/engine.js + render/effects.js into render/preview/fx.js for the WebView
// (the WebView has no require()). Run before packaging – install-mac.sh does it.
const fs = require("fs"), path = require("path");
const R = path.join(__dirname, "..", "render");
const wrap = (name) => `mods[${JSON.stringify("./" + name)}] = (function () { const module = { exports: {} }; const exports = module.exports;\n${fs.readFileSync(path.join(R, name), "utf8")}\nreturn module.exports; })();\n`;
const out = `// GENERATED by tools/bundle.js – do not edit. Source: render/engine.js, render/effects.js
(function () {
const mods = {};
const require = (n) => mods[n];
${wrap("engine.js")}
${wrap("effects.js")}
window.HL = { E: mods["./engine.js"], FX: mods["./effects.js"] };
})();
`;
fs.writeFileSync(path.join(R, "preview", "fx.js"), out);
console.log("preview/fx.js written", out.length, "bytes");
